# ============================================================================
#  gn_ad.py  -  v4.7  (NEW LAST WRITER, runs after gn_ac)
# ============================================================================
#  Replaces the main screen's Android-XML UI with the supplied HTML rendered in
#  a WebView, bridged to the EXISTING native functionality through a JavaScript
#  interface. Nothing functional is reimplemented: every bridge method calls the
#  same native method the old buttons called.
#
#  What this writer does:
#    * bundles the HTML UI as app/src/main/assets/offex_ui.html (fully inline -
#      CSS and SVG are embedded, so the shell makes no external network calls),
#    * wraps activity_main.xml in a FrameLayout that hosts a full-screen WebView
#      above the (still present, id-complete) native view tree, so every id the
#      generated Java looks up keeps resolving,
#    * grafts setupWebUi()/buildState()/pushState() and the OffexBridge JS
#      interface into MainActivity, and hooks state pushes into the existing
#      flows (loadMessages, createInbox, deleteActive, renderHistory, tick,
#      onResume, applyFeatureUI),
#    * lets an FCM push refresh the open WebView (FcmService -> MainActivity.onPush)
#      while still posting the system notification exactly as before,
#    * bumps 4.6 -> 4.7 (Config self-version, SupportActivity.VERSION, about strings).
#
#  Untouched: API endpoints/JSON fields, FCM + notification sounds, the support
#  screen, the AdMob placements, the notification-permission gate, the 7-locale
#  multi-language support, install analytics, the OTP precision fix, tappable
#  verification links, the circular logo and the remote appearance config.
# ============================================================================
import os, re, base64

ROOT = "android"; APP = ROOT + "/app"
RES = APP + "/src/main/res"
J = APP + "/src/main/java/online/mytempmail/app"
ASSETS = APP + "/src/main/assets"

HTML_B64 = ""
JAVA_B64 = ""


def R(p):
    with open(p, encoding="utf-8") as f:
        return f.read()


def W(p, s):
    with open(p, "w", encoding="utf-8") as f:
        f.write(s)


def REP(path, old, new, tag, count=1):
    s = R(path)
    if s.count(old) != count:
        raise SystemExit("gn_ad: anchor %s not unique (%d, expected %d) in %s"
                         % (tag, s.count(old), count, path))
    W(path, s.replace(old, new))
    print("AD: patched %s (%s)" % (path, tag))


# ===========================================================================
# 1 : bundle the HTML UI as an asset (inline CSS + inline SVG, no network)
# ===========================================================================
os.makedirs(ASSETS, exist_ok=True)
W(ASSETS + "/offex_ui.html", base64.b64decode(HTML_B64).decode("utf-8"))
print("AD: wrote assets/offex_ui.html (%d bytes)" % os.path.getsize(ASSETS + "/offex_ui.html"))

# ===========================================================================
# 2 : host the WebView - wrap the existing activity_main.xml (all ids intact)
# ===========================================================================
amp = RES + "/layout/activity_main.xml"
src = R(amp)
decl = '<?xml version="1.0" encoding="utf-8"?>'
inner = src.split("\n", 1)[1] if src.startswith(decl) else src
inner = inner.replace(
    '<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android"',
    '<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android"\n    android:id="@+id/nativeRoot"',
    1)
FRAME_OPEN = (
    decl + "\n"
    '<FrameLayout xmlns:android="http://schemas.android.com/apk/res/android"\n'
    '    android:id="@+id/webRoot"\n'
    '    android:layout_width="match_parent" android:layout_height="match_parent"\n'
    '    android:background="#020A27">\n')
WEBVIEW = (
    '    <WebView android:id="@+id/webUi"\n'
    '        android:layout_width="match_parent" android:layout_height="match_parent"\n'
    '        android:background="#020A27" android:scrollbars="none"\n'
    '        android:overScrollMode="never"/>\n')
wrapped = FRAME_OPEN + inner.rstrip("\n") + "\n" + WEBVIEW + "</FrameLayout>\n"
W(amp, wrapped)
print("AD: wrapped activity_main.xml (WebView host over the native tree)")

# ===========================================================================
# 3 : graft the WebView host + JS bridge into MainActivity.java
# ===========================================================================
M = J + "/MainActivity.java"
JAVA_BLOCK = base64.b64decode(JAVA_B64).decode("utf-8")

REP(M, 'import android.widget.Toast;',
    'import android.widget.Toast;\n'
    'import android.net.Uri;\n'
    'import android.webkit.JavascriptInterface;\n'
    'import android.webkit.WebSettings;\n'
    'import android.webkit.WebView;\n'
    'import android.webkit.WebViewClient;',
    "imports")

REP(M, '    private boolean notifGateShown=false;',
    '    private boolean notifGateShown=false;\n'
    '    private WebView webUi;\n'
    '    private static MainActivity live;\n'
    '    private String pickedDomain="";\n'
    '    private volatile String stateJson="{}";',
    "fields")

REP(M,
    '        if(!Prefs.address().isEmpty()){ activeCard.setVisibility(View.VISIBLE); addrText.setText(Prefs.address()); loadMessages(); startPolling(); startService(); }\n    }',
    '        if(!Prefs.address().isEmpty()){ activeCard.setVisibility(View.VISIBLE); addrText.setText(Prefs.address()); loadMessages(); startPolling(); startService(); }\n        setupWebUi();\n    }',
    "onCreate setupWebUi")

REP(M,
    '                    if(newPill!=null){ int nn=mails.size(); newPill.setText(nn+" "+getString(R.string.new_suffix)); newPill.setVisibility(nn>0?View.VISIBLE:View.GONE); }',
    '                    if(newPill!=null){ int nn=mails.size(); newPill.setText(nn+" "+getString(R.string.new_suffix)); newPill.setVisibility(nn>0?View.VISIBLE:View.GONE); }\n                    pushState();',
    "loadMessages push")

REP(M,
    '                    Toast.makeText(this,getString(R.string.toast_inbox_ready),Toast.LENGTH_SHORT).show();\n                    renderHistory(); loadMessages(); startPolling(); startService();',
    '                    Toast.makeText(this,getString(R.string.toast_inbox_ready),Toast.LENGTH_SHORT).show();\n                    renderHistory(); loadMessages(); startPolling(); startService();\n                    pushState();',
    "createInbox push")

REP(M,
    '                emptyText.setVisibility(View.VISIBLE); renderHistory(); Toast.makeText(this,getString(R.string.toast_inbox_deleted),Toast.LENGTH_SHORT).show(); });',
    '                emptyText.setVisibility(View.VISIBLE); renderHistory(); Toast.makeText(this,getString(R.string.toast_inbox_deleted),Toast.LENGTH_SHORT).show(); pushState(); });',
    "deleteActive push")

REP(M,
    '                historyBox.addView(row);\n            }\n        } catch(Exception e){}\n    }\n    private void loadMessages(){',
    '                historyBox.addView(row);\n            }\n        } catch(Exception e){}\n        pushState();\n    }\n    private void loadMessages(){',
    "renderHistory push")

REP(M,
    '        Ui.apply(this);\n        if(activeCard!=null&&activeCard.getVisibility()==View.VISIBLE){ loadMessages(); startPolling(); startService(); }',
    '        Ui.apply(this);\n        live=this;\n        pushState();\n        if(activeCard!=null&&activeCard.getVisibility()==View.VISIBLE){ loadMessages(); startPolling(); startService(); }',
    "onResume live+push")

REP(M,
    '    @Override protected void onPause(){\n        super.onPause();\n        MailService.appForeground=false;\n        stopPolling();\n    }',
    '    @Override protected void onPause(){\n        super.onPause();\n        live=null;\n        MailService.appForeground=false;\n        stopPolling();\n    }',
    "onPause live=null")

REP(M,
    '        countdownText.setText(getString(R.string.expires_in)+"  "+(left/3600)+"h "+((left%3600)/60)+"m "+(left%60)+"s");',
    '        countdownText.setText(getString(R.string.expires_in)+"  "+(left/3600)+"h "+((left%3600)/60)+"m "+(left%60)+"s");\n        pushState();',
    "tick push")

REP(M,
    '            if(emptyText!=null) Ui.setEmptyText(this);\n        } catch(Exception e){}\n    }\n}',
    '            if(emptyText!=null) Ui.setEmptyText(this);\n        } catch(Exception e){}\n        pushState();\n    }\n' + JAVA_BLOCK + '}',
    "append bridge block")

# ===========================================================================
# 4 : FCM push refreshes the open WebView (notification still posted always)
# ===========================================================================
REP(J + "/FcmService.java",
    '            Notifier.mail(this, title, body);',
    '            Notifier.mail(this, title, body);\n'
    '            // If the app is open, refresh the WebView state too.\n'
    '            try { if(MailService.appForeground) MainActivity.onPush(); } catch(Exception e){}',
    "fcm push hook")

# ===========================================================================
# 5 : new strings for the bridge dialogs, all 7 locales
# ===========================================================================
NEW_STRINGS = {
    "":    ("Delete %1$s? This cannot be undone.", "Cancel", "Choose domain"),
    "-hi": ("%1$s को हटाएँ? इसे वापस नहीं लाया जा सकता।", "रद्द करें", "डोमेन चुनें"),
    "-es": ("¿Eliminar %1$s? No se puede deshacer.", "Cancelar", "Elegir dominio"),
    "-pt": ("Excluir %1$s? Nao pode ser desfeito.", "Cancelar", "Escolher dominio"),
    "-ar": ("هل تريد حذف %1$s؟ لا يمكن التراجع عن ذلك.", "إلغاء", "اختر النطاق"),
    "-ru": ("Удалить %1$s? Это нельзя отменить.", "Отмена", "Выбрать домен"),
    "-in": ("Hapus %1$s? Tidak bisa dibatalkan.", "Batal", "Pilih domain"),
}
for loc, (msg, cancel, domain) in NEW_STRINGS.items():
    p = RES + "/values" + loc + "/strings.xml"
    if not os.path.exists(p):
        continue
    s = R(p)
    if "confirm_delete_msg" in s:
        print("AD: (skip) bridge strings already present in %s" % p)
        continue
    add = ('    <string name="confirm_delete_msg">%s</string>\n'
           '    <string name="cancel">%s</string>\n'
           '    <string name="choose_domain">%s</string>\n'
           '</resources>\n') % (msg, cancel, domain)
    s = s.replace("</resources>", add, 1)
    W(p, s)
    print("AD: added bridge strings to %s" % p)

# ===========================================================================
# 6 : version bump 4.6 -> 4.7 (self-version + about strings)
# ===========================================================================
REP(J + "/Config.java",
    '            if(latest.equals("4.6")) return;',
    '            if(latest.equals("4.7")) return;',
    "self-version 4.7")

REP(J + "/SupportActivity.java",
    '    public static final String VERSION = "4.6";',
    '    public static final String VERSION = "4.7";',
    "support self-version 4.7")

for loc in ["", "-hi", "-es", "-pt", "-ar", "-ru", "-in"]:
    p = RES + "/values" + loc + "/strings.xml"
    if not os.path.exists(p):
        continue
    s = R(p)
    s2 = re.sub(r'(name="about_version">[^<]*?)4\.6(<)', r"\g<1>4.7\g<2>", s)
    if s2 == s:
        print("AD: (skip) about_version 4.6 not present in %s" % p)
    else:
        W(p, s2)
        print("AD: patched %s (about_version 4.7)" % p)

print("AD: done")
